def infer_fill(g):
    h,w=len(g),len(g[0])
    cells=[(i,j,v) for i,r in enumerate(g) for j,v in enumerate(r) if v]
    best=None
    from collections import Counter
    for p in range(2,17):
        for ai in range(p):
            for aj in range(p):
                cnt={}
                for i,j,v in cells:
                    cnt.setdefault((ai*i+aj*j)%p,Counter())[v]+=1
                mp={k:c.most_common(1)[0][0] for k,c in cnt.items()}
                score=sum(c[mp[k]] for k,c in cnt.items())/len(cells)
                if best is None or score>best[0]:
                    best=(score,p,ai,aj,mp)
    score,p,ai,aj,mp=best
    return [[v if v else mp.get((ai*i+aj*j)%p) for j,v in enumerate(r)] for i,r in enumerate(g)],(score,p,ai,aj)
